"""Where the routes read sign-ups from. Do not edit this file.

The data pipeline has already loaded the sign-ups; this lab reads that result from
fixtures/signups.json, so no database is needed. The routes receive a repository through
the get_repository dependency, and tests replace it with their own.
"""

import json
from pathlib import Path

SIGNUPS_FILE = Path(__file__).resolve().parents[2] / "fixtures" / "signups.json"


class SignupRepository:
    """Sign-up dicts kept in memory, in id order."""

    def __init__(self, signups):
        self._signups = [dict(s) for s in signups]

    def get(self, signup_id):
        """Return the sign-up dict with this id, or None."""
        for signup in self._signups:
            if signup["id"] == signup_id:
                return dict(signup)
        return None

    def list_by_session(self, session, limit, offset):
        """Return at most `limit` sign-ups of `session`, skipping the first `offset` of them."""
        matching = [dict(s) for s in self._signups if s["session"] == session]
        return matching[offset : offset + limit]

    def add(self, data):
        """Store a new sign-up (status "confirmed", next free id) and return it."""
        signup = {"id": max((s["id"] for s in self._signups), default=0) + 1, **data, "status": "confirmed"}
        self._signups.append(signup)
        return dict(signup)


def load_repository():
    """Return a repository holding the pipeline's loaded sign-ups."""
    return SignupRepository(json.loads(SIGNUPS_FILE.read_text(encoding="utf-8")))


_shared = None


def get_repository():
    """FastAPI dependency: the one repository this running app shares between requests."""
    global _shared
    if _shared is None:
        _shared = load_repository()
    return _shared
